    const startMarker = '/* @RADIAL_TOP_LAYER_CSS_START */';
    const endMarker = '/* @RADIAL_TOP_LAYER_CSS_END */';
    const startIdx = fullCss.indexOf(startMarker);
    const endIdx = fullCss.indexOf(endMarker);
