    const search = String(loc?.search || '');
    const segMatch = pathname.match(/^\/c\/([^/?#]+)(?:\/|$)/i) || search.match(/[?&]cascadeId=([^&#]*)/i);
    const rawTokens = segMatch ? safeDecode(segMatch[1]).split('+').map(s => s.trim()).filter(Boolean) : [];
