    if (proxyDrawerArrow) proxyDrawerArrow.textContent = isProxyExpanded ? t('drawer.shortCollapse') : t('drawer.shortExpand');
    btnToggleProxy?.setAttribute('aria-expanded', String(isProxyExpanded));
